resource "aws_security_group" "rds" {
  name        = "saas-primary-rds-sg"
  vpc_id      = var.vpc_id
  description = "RDS PostgreSQL access"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidrs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "saas-primary-rds-sg" }
}

